        "status": "NOT_APPLICABLE_TO_THIS_QUESTION"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s12"]}],
        "rationale": "The passage expressly retains overall operational responsibility for intermediaries meeting the stated issuance and intended dealing or advising conditions.",
        "status": "SUPPORTED"
