      },
      "followup_questions": [],
      "pair": "p2",
      "question_relation": {
        "evidence": [{"span_ids": ["s4"]}, {"span_ids": ["s3"]}],
        "rationale": "This claim specifies what confirmation and demonstration must cover, whereas the typed question asks only whether a request activates demonstration. The question expressly assumes the footnote does not remove that condition.",
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s4"]}],
        "rationale": "Footnote 5 expressly includes compliance with paragraphs 10–13 as minimum content. Their complete substantive requirements and the footnote's independent effect on timing remain unresolved.",
